if (counts[first] >= 3) {
  counts[first] -= 3;
  search([...sets, Block(first)]);
  counts[first] += 3;
}
if (first < 27 &&
    first % 9 <= 6 &&
    counts[first + 1] > 0 &&
    counts[first + 2] > 0) {
  counts[first]--;
  counts[first + 1]--;
  counts[first + 2]--;
  search([...sets, Block(first, sequence: true)]);
  counts[first]++;
  counts[first + 1]++;
  counts[first + 2]++;
}
